DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT114-S4-Q3$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S4-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT114-S4-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$Obviously no animals would survive without plants.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$The dependence is mutual.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Many plant species exist only because animals pollinate, fertilize, and spread their seeds. Without animals, plants' photosynthesis would deplete the atmosphere's carbon dioxide.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"But the dependence is mutual" is the pivot. Spell out "mutual": animals depend on plants, and plants also depend on animals. The two "Also" points are evidence for the plant-on-animal side.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Animals and plants depend on each other.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT114-S4-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This makes photosynthesis the whole story. The journalist's point covers pollination and seeds too, and this choice also says animals are needed for photosynthesis to occur, which the passage doesn't say.$batch10$), ($batch10$B$batch10$, $batch10$This is part of the opening concession, not the conclusion.$batch10$), ($batch10$C$batch10$, $batch10$This picks up only the carbon dioxide point and turns it into a claim about Earth's chemistry. It leaves out the mutual dependence.$batch10$), ($batch10$D$batch10$, $batch10$The passage says plants would deplete carbon dioxide, not oxygen. It also isn't the conclusion.$batch10$), ($batch10$E$batch10$, $batch10$Animals depend on plants, and plants depend on animals. That is what "the dependence is mutual" means.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT114-S4-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
